function renderWritingWorkshop(){let result=null,analysisText='',filter='all',ignored=new Set(),history=[];
 const preferences=read('writing-options',{ignoreQuotes:true,genre:'general'});
 const labels={norm:'Skrivemåte',grammar:'Grammatikk',style:'Stil og flyt'};
 const genreAdvice={general:['Kven skal lese teksten, og kva vil du oppnå?','Les høgt og kontroller bøyinga på ord du er usikker på.','Vel ei endring du kan forklare med eigne ord.'],story:['Hald kontroll på fortid og notid i forteljinga.','Bruk handling og sansedetaljar der det gjer teksten levande.','La avsnitta følgje skifte i tid, stad eller handling.'],argument:['Gjer hovudpåstanden tydeleg.','Grunngi påstandane, og skil fakta frå meiningar.','Ta med eit relevant motargument og vis kvifor du er samd eller usamd.'],factual:['Start avsnitt med det viktigaste poenget.','Forklar fagord første gongen dei blir brukte.','Vis til kjelder for opplysningar som kan kontrollerast.']};
 main.innerHTML=intro('Ein tekst. Mange gode språkval.','Undersøk konkrete tekststader, forstå råda og vel endringane sjølv.','SKRIVEVERKSTADEN')+`<section class="writing-layout"><div class="panel writing-editor"><div class="section-head"><h2>Teksten din</h2><span class="tag">Analyse på eininga di</span></div><div class="lex-filters writing-options"><div><label for="writing-genre">Kva skriv du?</label><select id="writing-genre"><option value="general">Ein valfri tekst</option><option value="story">Forteljing</option><option value="argument">Argumenterande tekst</option><option value="factual">Fagtekst</option></select></div><div><label for="prompt-select">Treng du ein start?</label><select id="prompt-select"><option value="">Vel ei skriveoppgåve …</option><option>Fortel om ein dag som tok ei uventa vending. Bruk minst tre verb i preteritum.</option><option>Argumenter for ei endring på skulen. Ta med påstand, grunngiving og eit motargument.</option><option>Forklar eit tema du kan noko om. Definer fagorda og vis til kjelder.</option></select></div></div><p id="writing-prompt" class="small"></p><label for="draft">Skriv eller lim inn teksten din</label><textarea id="draft" spellcheck="false" maxlength="30000" placeholder="Her er det rom for å prøve …">${esc(draft)}</textarea><div class="text-area-footer"><span id="wordcount"></span><span id="save-status"></span></div><div class="button-row"><button class="button" id="analyze">Undersøk teksten ✧</button><button class="button secondary" id="undo-edit" disabled>Angre siste endring ↶</button><button class="plain" id="download">Last ned tekst ↓</button></div><label class="inline-check" style="margin-top:18px"><input type="checkbox" id="ignore-quotes" ${preferences.ignoreQuotes?'checked':''}> Hopp over tekst i «sitat», “sitat” og "sitat"</label><p class="small muted">Regelbasert rettleiing, ikkje ein full språkkontroll. Ingen tekst blir send til ei KI-teneste. Ordboklenkjer sender berre ordet du vel å slå opp.</p><details id="marked-preview"><summary>Sjå markerte tekststader</summary><div id="text-highlights" class="text-highlights">Undersøk teksten for å sjå språklege spor.</div></details><div class="writer-metrics" id="writer-metrics"></div></div><aside class="panel writer-feedback"><div class="section-head"><h2>Språklege spor</h2><span class="tag" id="finding-count">Klar til å lese</span></div><div id="writing-feedback" aria-live="polite"><div class="empty"><span class="rule-icon">✎</span><h3>Din tekst, dine val.</h3><p>Skriv litt og vel «Undersøk teksten». Du får råd om konkrete ord, grammatikk og flyt.</p></div></div></aside></section><section class="panel"><div class="section-head"><h2>Neste gjennomlesing</h2><span class="small muted">Det automatiske ikkje kan avgjere</span></div><div id="genre-advice" class="checklist"></div><details><summary>Kva sjekkar skriveguiden – og kva sjekkar han ikkje?</summary><div><p>Guiden ser etter utvalde bokmålsformer, nokre mønster i verbbøying, samsvar, ordstilling, og/å, gjentakingar og teiknsetjing. Stilråd handlar om mellom anna setningslengd, substantivtunge uttrykk og variasjon. Sjanger påverkar kva råd du får.</p><p>Han forstår ikkje heile innhaldet, vurderer ikkje kjelder og finn ikkje alle språkfeil. Godkjende variantar som «komme», «skole», «også», «begynte» og «nå» blir ikkje endra berre fordi dei liknar bokmål. Eit råd kan vere feil i din samanheng. Sitat blir hoppa over som standard; eit uavslutta sitat vernar resten av teksten.</p><p>Ordval blir kontrollert i <a href="https://ordbokene.no" target="_blank" rel="noopener">Ordbøkene</a>. Råda om å bruke tydelege verb er inspirerte av <a href="https://sprakradet.no/godt-og-korrekt-sprak/praktisk-sprakbruk/nynorskhjelp/substantivtunge-setningar/" target="_blank" rel="noopener">Språkrådets nynorskhjelp</a>. Reglane og døma i appen er laga for øving.</p></div></details></section><div class="section-head"><h2>Omskrivingar du kan lære av</h2><p>Gjer språket meir presist</p></div><div class="stack">${REWRITES.map((r,i)=>`<details ${i===0?'open':''}><summary>${r[0]}</summary><div><div class="compare"><div><small>UTGANGSPUNKT</small>${r[1]}</div><div><small>EIT MOGLEG ALTERNATIV</small>${r[2]}</div></div><p style="margin:14px 0 0">${r[3]}</p></div></details>`).join('')}</div>`;
 $('#writing-genre').value=preferences.genre;
 function options(){return {ignoreQuotes:$('#ignore-quotes').checked,genre:$('#writing-genre').value}}
 function update(){draft=$('#draft').value;$('#wordcount').textContent=`${draft.trim()?draft.trim().split(/\s+/).length:0} ord · ${draft.length} teikn`;$('#save-status').textContent=save('draft',draft)?'Lagra på denne eininga':'Kunne ikkje lagre – last ned teksten';$('#undo-edit').disabled=!history.length}
 function genre(){const g=$('#writing-genre').value;$('#genre-advice').innerHTML=genreAdvice[g].map(t=>`<label><input type="checkbox">${t}</label>`).join('')}
 function invalidate(){if(!result)return;$('#finding-count').textContent='Teksten er endra';$('#writing-feedback').innerHTML='<div class="tip"><strong>Undersøk teksten på nytt.</strong><p>Råda må følgje den nye teksten før du kan bruke eit forslag.</p></div>';$('#text-highlights').textContent='Teksten er endra. Undersøk teksten på nytt.';$('#writer-metrics').innerHTML='';result=null;ignored.clear()}
 function run(){update();analysisText=draft;ignored.clear();result=WritingEngine.analyze(draft,options());filter='all';show()}
 function highlight(active){const sorted=[...active].sort((a,b)=>a.start-b.start||(a.end-a.start)-(b.end-b.start));let html='',cursor=0;for(const issue of sorted){if(issue.start<cursor)continue;html+=esc(draft.slice(cursor,issue.start))+`<mark class="mark-${issue.category}">${esc(draft.slice(issue.start,issue.end))}</mark>`;cursor=issue.end}return html+esc(draft.slice(cursor))}
 function show(){const active=result.issues.filter(i=>!ignored.has(i.id)),visible=active.filter(i=>filter==='all'||i.category===filter);$('#finding-count').textContent=`${active.length} spor`;const m=result.metrics;$('#writer-metrics').innerHTML=`<div><b>${m.words}</b><small>ord</small></div><div><b>${m.sentences}</b><small>setningar*</small></div><div><b>${m.paragraphs}</b><small>avsnitt</small></div><div><b>${m.average}</b><small>ord per setning*</small></div><p>*Omtrentleg, basert på skiljeteikn. Ikkje ein karakter eller kvalitetsmålestokk.</p>`;$('#text-highlights').innerHTML=highlight(active)||'Ingen tekst enno.';
  $('#writing-feedback').innerHTML=`<div class="feedback-tabs" role="group" aria-label="Filtrer språklege spor">${[['all','Alle'],...Object.entries(labels)].map(([k,label])=>`<button class="tab ${filter===k?'selected':''}" data-feedback-filter="${k}" aria-pressed="${filter===k}">${label} <span>${k==='all'?active.length:active.filter(i=>i.category===k).length}</span></button>`).join('')}</div>${!draft.trim()?'<div class="empty">Skriv litt først, så kan vi undersøkje teksten.</div>':!active.length?'<div class="tip"><strong>Ingen treff i desse reglane.</strong><p>Det betyr ikkje at teksten er feilfri. Bruk sjekklista, les høgt og slå opp ord du er usikker på.</p></div>':!visible.length?'<p class="empty">Ingen spor i denne kategorien.</p>':visible.map(i=>`<article class="writing-issue issue-${i.category}" id="finding-${i.start}"><div class="section-head"><span class="tag">${labels[i.category]}</span><button class="plain issue-select" data-issue="${esc(i.id)}">Vis i teksten ↖</button></div><h3>${esc(i.title)}</h3><p class="issue-context">${esc(draft.slice(Math.max(0,i.start-30),i.start))}<strong>${esc(i.original)}</strong>${esc(draft.slice(i.end,Math.min(draft.length,i.end+30)))}</p><p>${esc(i.message)}</p>${i.replacements.length?`<div class="issue-replacements">${i.replacements.map((r,j)=>`<button class="replacement" data-issue="${esc(i.id)}" data-replacement="${j}">Bruk «${esc(r)}» <span>↵</span></button>`).join('')}</div>`:''}<div class="issue-tools"><button class="plain issue-ignore" data-issue="${esc(i.id)}">Ikkje relevant her</button>${/^[\p{L}]+$/u.test(i.original)?`<a href="https://ordbokene.no/nno/search?q=${encodeURIComponent(i.original)}&dict=nn" target="_blank" rel="noopener">Slå opp ordet ↗</a>`:`<a href="${i.source}" target="_blank" rel="noopener">Språkressurs ↗</a>`}</div></article>`).join('')}<p class="small muted">Råd skal vurderast i samanheng. Ingen endringar blir gjorde før du vel eit forslag.</p>${active.length?'<button class="plain" id="download-feedback">Last ned tekst og råd ↓</button>':''}`;
  $$('[data-feedback-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.feedbackFilter;show()});
  const find=id=>result.issues.find(i=>i.id===id);
  $$('.replacement').forEach(b=>b.onclick=()=>{if(draft!==analysisText){invalidate();return}const issue=find(b.dataset.issue);history.push(draft);if(history.length>30)history.shift();draft=WritingEngine.apply(draft,issue,issue.replacements[+b.dataset.replacement]);$('#draft').value=draft;run();toast('Forslaget er brukt. Du kan angre endringa.')});
  $$('.issue-ignore').forEach(b=>b.onclick=()=>{ignored.add(b.dataset.issue);show()});
  $$('.issue-select').forEach(b=>b.onclick=()=>{const issue=find(b.dataset.issue),el=$('#draft');el.focus();el.setSelectionRange(issue.start,issue.end);el.scrollIntoView({behavior:'smooth',block:'center'})});
  if($('#download-feedback'))$('#download-feedback').onclick=()=>download('nynorsk-tekst-og-rad.txt',draft+'\n\nSPRÅKLEGE SPOR – IKKJE FULL SPRÅKVASK\n\n'+active.map(i=>`${labels[i.category]}: ${i.title}\n«${i.original}»\n${i.message}\n${i.replacements.length?'Forslag: '+i.replacements.join(' / '):''}`).join('\n\n'));
 }
 $('#draft').oninput=()=>{history=[];update();invalidate()};$('#analyze').onclick=run;$('#download').onclick=()=>download('nynorsktekst.txt',draft);$('#undo-edit').onclick=()=>{if(!history.length)return;$('#draft').value=history.pop();run();toast('Den førre teksten er gjenoppretta.')};$('#prompt-select').onchange=()=>{$('#writing-prompt').textContent=$('#prompt-select').value};$('#writing-genre').onchange=()=>{save('writing-options',options());genre();if(result)run()};$('#ignore-quotes').onchange=()=>{save('writing-options',options());if(result)run()};update();genre();
}
